def score(program: str) -> float:
    depth = max_d = colons = 0
    for c in program:
        if c in '({[': depth += 1; max_d = max(max_d, depth)
        elif c in ')}]': depth = max(0, depth - 1)
        elif c == ':': colons += 1
    return min(1.0, max(0.0, (max_d + colons / 8) / 12))

import ast, zlib

def score(program: str) -> float:
    salt = 9973
    try:
        tree = ast.parse(program)
        kinds = {type(n).__name__ for n in ast.walk(tree)}
        blob = ",".join(sorted(kinds)).encode()
        h = zlib.crc32(blob)
        return (h % salt) / salt
    except Exception:
        return 0.37

